if (currentToken !== expectedVersionToken) {
  outcome = { conflict: true, currentToken };
  // CC1 (checklist cold cache; the CD-M2 entry-exception pattern): the FIRST invocation runs against the instance's LOCAL
  // cache — `null` (or stale) on a cold server instance — and returning `undefined` there aborts WITHOUT consulting the
  // server, so an edit of an EXISTING document with its correct token was refused as a conflict. The first run therefore
  // re-submits the value it saw, unchanged: RTDB compares it with the server's value and either commits that identical
  // value (the cache was right: a genuine conflict, nothing changes) or re-runs this function with the server's value.
  // Every later run (the server's value) aborts on a mismatch exactly as before.
  return runs === 1 ? current : undefined;
}
